<?php

namespace App\Exceptions;

use Illuminate\Foundation\Exceptions\Handler as ExceptionHandler;
use Illuminate\Http\Response;
use Illuminate\Support\Facades\App;
use Illuminate\Support\Facades\Config;
use Inertia\Inertia;
use Symfony\Component\HttpFoundation\Response as SymfonyResponse;
use Throwable;

class Handler extends ExceptionHandler
{
    const HTTP_PAGE_EXPIRED = 419;

    /**
     * The list of the inputs that are never flashed to the session on validation exceptions.
     *
     * @var array<int, string>
     */
    protected $dontFlash = [
        'current_password',
        'password',
        'password_confirmation',
    ];

    /**
     * Register the exception handling callbacks for the application.
     */
    public function register(): void
    {
        $this->reportable(function (Throwable $e) {
            //
        });
    }

    public function render($request, Throwable $e)
    {
        /** @var Response $response */
        $response = parent::render($request, $e);
        // ローカル環境ではデバッグ用の画面を表示させたいため、それ以外の環境でのみカスタムエラーページを表示させる
        if (! App::environment(['local']) && $response->status() >= SymfonyResponse::HTTP_BAD_REQUEST) {
            if ($response->status() === self::HTTP_PAGE_EXPIRED) {
                return back()->with([
                    'message' => 'The page expired, please try again.',
                ]);
            } else {
                return Inertia::render('Error', [
                    'ecnaviBaseUrl' => Config::string('ecnavi.app.base_url'),
                    'statusCode' => $response->status(),
                ])
                    ->toResponse($request)
                    ->setStatusCode($response->status());
            }
        }

        return $response;
    }
}

